item.command:
/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { importStock } from './src/entry.js';

const output = importStock(' ab-2 ,5,8');
assert.deepEqual(output, { product_code: 'AB-2', units: 0, schema: 2 });
assert.deepEqual(importStock('a,5,2'), { product_code: 'A', units: 3, schema: 2 });
let invalidNumeric;
try {
  importStock('x,no,1');
  throw new Error('Expected invalid numeric input to throw');
} catch (error) {
  assert.equal(error.message, 'invalid count');
  invalidNumeric = error.message;
}

const answer = {
  files: [
    { path: 'src/entry.js', symbol: 'importStock' },
    { path: 'src/input/csv.js', symbol: 'parseStock' },
    { path: 'src/domain/stock.js', symbol: 'normalizeStock' },
    { path: 'src/domain/sku.js', symbol: 'canonicalSku' },
    { path: 'src/output/wire.js', symbol: 'wireStock' }
  ],
  output,
  invalid_numeric: invalidNumeric,
  reserved_applied_before_clamp: true
};
await writeFile('answer.json', "'`${JSON.stringify(answer, null, 2)}'"\\n"'`);
assert.deepEqual(JSON.parse(await readFile('"'answer.json', 'utf8')), answer);
console.log('PASS: requested inputs, reserved-stock subtraction, and answer.json readback');
NODE"

